// Session types (ST-1 of docs/ai/session-type-plan.md, migration v85): the editable list in Settings -> Tags & Presets.
//
// One registry, training.activity_types. A system type is written by an active platform admin in the platform workspace;
// a club type by the club's active admin in that club's workspace. The key is the identity (generated by the server);
// a rename changes only the label; an archive takes the type out of the pickers and leaves it on the sessions that hold
// it. Every write is one transaction: the acting user set (optimove.session_type_actor), the requestKey replay, the
// rights (users first, PR #346, through training.session_type_basis), the type row FOR UPDATE, the write, its log row
// (the request record), COMMIT. The database guards of v85 check the same right again.
//
// Who reads: a coach account in a platform, club, team or private-coach workspace (the types it may offer). Everyone
// else - an athlete, a type of another club - gets the identical 404 (ADR-006).
import crypto from "node:crypto";
import { pool } from "./db.js";
import { boundedText } from "./metricTextRules.js";
import { holdsClubAdminRole, isPlatformAdministrator } from "./authz.js";
import { can, clubScope, teamScope } from "./permissions.js";

export const LABEL_MAX = 60;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const KEY = /^(?:[a-z][a-z0-9_]{1,40}|c_[0-9a-f]{8}_[a-z0-9_]{1,40})$/;

export class SessionTypeError extends Error {
  constructor(status, code, message, extra = {}) {
    super(message);
    this.status = status;
    this.code = code;
    this.extra = extra;
  }
}
const notFound = () => new SessionTypeError(404, "not_found", "Not found.");
const bad = (code, message) => new SessionTypeError(400, code, message);
const conflict = (code, message, extra) => new SessionTypeError(409, code, message, extra);

// Test-only seams: beforeCommit(client), commit(client) in place of the COMMIT, commitTimeoutMs.
export const testHooks = {};
export const COMMIT_ANSWER_TIMEOUT_MS = 15_000;
function withinBound(promise, ms) {
  let timer;
  const timeout = new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(`no answer within ${ms} ms`)), ms); });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

// The club of a team, active (null: none).
async function teamClub(client, teamId) {
  const r = await client.query(`select club_id from public.teams where id = $1 and is_active = true`, [teamId]);
  return r.rowCount ? String(r.rows[0].club_id) : null;
}

// Roles V-1 (docs/ai/roles-v-steps-plan.md section 2.2): a club or team workspace sees its club's types only with
// presets.use there (the club's licence is inside can(); a platform admin passes); without it, the system types only.
const SCOPE_OF = Object.freeze({ club: clubScope, team: teamScope });
const presetsAt = (ctx, w) => can(ctx.authz, "presets.use", SCOPE_OF[w.type](String(w.scopeId)));

// The club whose types this workspace sees (null: system types only), or a refusal.
async function workspaceClub(ctx, client) {
  // A view workspace (the entry gate of routes/sessionTypes.js checked presets.use and resolved it read only): its club,
  // or its team's club, to read; never a writer (writableOwner).
  if (ctx.moduleView) {
    const scope = ctx.moduleView.scope;
    if (!scope || !UUID.test(scope.id)) throw notFound();
    if (scope.type === "club") {
      const r = await client.query(`select id from public.clubs where id = $1 and coalesce(is_active, true)`, [scope.id]);
      if (!r.rowCount) throw notFound();
      return String(r.rows[0].id);
    }
    const clubId = await teamClub(client, scope.id);
    if (!clubId) throw notFound();
    return clubId;
  }
  if (ctx.accountType !== "coach") throw notFound();
  const w = ctx.workspace;
  if (!w) throw notFound();
  if (w.type === "platform" || w.type === "private_coach") return null;
  if (w.type === "club") return presetsAt(ctx, w) ? String(w.scopeId) : null;
  if (w.type === "team") {
    const clubId = await teamClub(client, w.scopeId);
    if (!clubId) throw notFound();
    return presetsAt(ctx, w) ? clubId : null;
  }
  throw notFound();
}

const view = (row) => ({
  key: row.key, label: row.label, ownerScope: row.owner_scope, active: row.is_active, sortOrder: row.sort_order,
});

// Which owner this caller writes in this workspace, or null.
function writableOwner(ctx) {
  const w = ctx.workspace;
  if (ctx.moduleView || ctx.accountType !== "coach" || !w) return null;
  if (w.type === "platform" && isPlatformAdministrator(ctx.authz)) return { ownerScope: "system", clubId: null };
  if (w.type === "club" && holdsClubAdminRole(ctx.authz, w.scopeId) && presetsAt(ctx, w)) return { ownerScope: "club", clubId: String(w.scopeId) };
  return null;
}

export async function listSessionTypes(ctx) {
  const client = await pool.connect();
  try {
    const clubId = await workspaceClub(ctx, client);
    const rows = (await client.query(
      `select key, label, owner_scope, is_active, sort_order from training.activity_types
        where owner_scope = 'system' or owner_club_id = $1
        order by is_active desc, sort_order, lower(label), key`, [clubId],
    )).rows;
    const owner = writableOwner(ctx);
    return {
      types: rows.map((r) => ({ ...view(r), editable: Boolean(owner && owner.ownerScope === r.owner_scope) })),
      canAdd: owner ? owner.ownerScope : null,
    };
  } finally {
    client.release();
  }
}

function labelOf(body, field = "label") {
  const raw = body?.[field];
  if (typeof raw !== "string" || !boundedText(raw.trim(), LABEL_MAX)) throw bad("invalid_label", `${field} is 1-${LABEL_MAX} visible characters on one line.`);
  return raw.trim();
}
function requestKeyOf(body) {
  if (typeof body?.requestKey !== "string" || !UUID.test(body.requestKey)) throw bad("invalid_request_key", "requestKey must be a UUID.");
  return body.requestKey.toLowerCase();
}
function only(body, allowed) {
  if (!body || typeof body !== "object" || Array.isArray(body)) throw bad("invalid_body", "The request body must be a JSON object.");
  for (const k of Object.keys(body)) if (!allowed.includes(k)) throw bad("invalid_body", `Unknown field: ${k}.`);
}
const hashOf = (value) => crypto.createHash("sha256").update(JSON.stringify(value)).digest("hex");

export function generatedKey(ownerScope, label, randomHex = crypto.randomBytes(4).toString("hex")) {
  const slug = label.normalize("NFKD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 30) || "type";
  return `${ownerScope === "club" ? "c" : "s"}_${randomHex}_${slug}`;
}

// One write: the rights first (users first, PR #346: the user, its role row and the club FOR SHARE), then the replay -
// answered only while the caller still holds the right for the type's owner (security review of ST-1, MEDIUM) - then
// the type row, the write and its log row.
async function write(ctx, { requestKey, hash, run }) {
  const owner = writableOwner(ctx);
  if (!owner) throw notFound();
  const client = await pool.connect();
  let destroyed = false;
  try {
    await client.query("begin");
    await client.query("set local lock_timeout = '3s'");
    await client.query("set local statement_timeout = '10s'");
    await client.query(`select set_config('optimove.session_type_actor', $1 || ':' || pg_current_xact_id()::text, true)`, [ctx.userId]);
    const basis = (await client.query(`select training.session_type_basis($1, $2, $3) as b`, [ctx.userId, owner.ownerScope, owner.clubId])).rows[0].b;
    if (!basis) throw notFound();
    // The same (user, requestKey) is serialized before the replay read (the code review of ST-1): a resend while the
    // first is still in flight waits for it and replays, instead of meeting its effect as a label or row conflict.
    // Taken after the rights rows, so users-first holds.
    await client.query(`select pg_advisory_xact_lock(hashtextextended($1 || ':' || $2, 85))`, [ctx.userId, requestKey]);
    const seen = (await client.query(
      `select c.request_hash, t.key, t.label, t.owner_scope, t.owner_club_id, t.is_active, t.sort_order
         from training.activity_type_changes c join training.activity_types t on t.key = c.type_key
        where c.performed_by_user_id = $1 and c.request_key = $2`, [ctx.userId, requestKey],
    )).rows[0];
    if (seen) {
      await client.query("rollback");
      if (seen.owner_scope !== owner.ownerScope || String(seen.owner_club_id ?? "") !== String(owner.clubId ?? "")) throw notFound();
      if (seen.request_hash !== hash) throw conflict("request_key_reused", "This requestKey was used for another change.");
      return { type: view(seen), replayed: true };
    }
    const result = await run(client, { owner, basis });
    // Every deferred guard now (the log row), so a refusal is definite before the COMMIT.
    await client.query("set constraints all immediate");
    if (testHooks.beforeCommit) await testHooks.beforeCommit(client);
    // The bounded COMMIT (the database review of ST-1): an answer that never comes is "not confirmed", never "not
    // saved"; the connection is closed, and the same requestKey reads the saved outcome or writes it once.
    try {
      const commit = testHooks.commit ? testHooks.commit(client) : client.query("commit");
      commit.catch(() => {});
      await withinBound(commit, testHooks.commitTimeoutMs ?? COMMIT_ANSWER_TIMEOUT_MS);
    } catch (error) {
      if (error?.code && /^(23|42)/.test(error.code)) throw error;
      destroyed = true;
      client.release(true);
      throw new SessionTypeError(503, "outcome_unknown", "The result is not confirmed. Send the same request again to check it.");
    }
    return { ...result, replayed: false };
  } catch (error) {
    if (!destroyed) await client.query("rollback").catch(() => {});
    if (error instanceof SessionTypeError) throw error;
    if (error?.code === "23505" && /activity_types_owner_label_live_key/.test(error.constraint ?? error.message ?? "")) {
      throw conflict("label_taken", "A session type with this name already exists.");
    }
    // The same requestKey sent twice at once: the second insert of the log row meets the first (security review, LOW).
    if (error?.code === "23505" && /activity_type_changes_request_key/.test(error.constraint ?? error.message ?? "")) {
      throw conflict("try_again", "The same request is being saved. Send it again to read its result.");
    }
    if (error?.code === "55P03" || error?.code === "40P01" || error?.code === "57014") throw conflict("try_again", "The list is being changed. Try again.");
    if (error?.code === "42501") throw notFound();
    throw error;
  } finally {
    if (!destroyed) client.release();
  }
}

// The type row FOR UPDATE, after write() locked the rights (users first, PR #346); another owner's type is the 404.
async function lockedType(client, owner, key) {
  const row = (await client.query(
    `select key, label, owner_scope, owner_club_id, is_active, sort_order from training.activity_types where key = $1 for update`, [key],
  )).rows[0];
  if (!row || row.owner_scope !== owner.ownerScope || String(row.owner_club_id ?? "") !== String(owner.clubId ?? "")) throw notFound();
  return row;
}

async function log(client, ctx, { key, action, oldLabel, newLabel, basis, requestKey, hash }) {
  await client.query(
    `insert into training.activity_type_changes (type_key, action, old_label, new_label, performed_by_user_id, basis, request_key, request_hash)
     values ($1, $2, $3, $4, $5, $6, $7, $8)`, [key, action, oldLabel, newLabel, ctx.userId, basis, requestKey, hash],
  );
}

export async function createSessionType(ctx, body) {
  // The rights before the body (security review, LOW): a caller who may not write gets the 404 whatever it sends.
  const owner = writableOwner(ctx);
  if (!owner) throw notFound();
  only(body, ["requestKey", "label"]);
  const requestKey = requestKeyOf(body);
  const label = labelOf(body);
  const hash = hashOf({ op: "create", label, ownerScope: owner.ownerScope, clubId: owner.clubId });
  return write(ctx, {
    requestKey, hash,
    run: async (client, { basis }) => {
      const key = generatedKey(owner.ownerScope, label);
      const row = (await client.query(
        `insert into training.activity_types (key, label, owner_scope, owner_club_id, created_by_user_id)
         values ($1, $2, $3, $4, $5) returning key, label, owner_scope, is_active, sort_order`,
        [key, label, owner.ownerScope, owner.clubId, ctx.userId],
      )).rows[0];
      await log(client, ctx, { key, action: "create", oldLabel: null, newLabel: label, basis, requestKey, hash });
      return { type: view(row) };
    },
  });
}

function keyOf(raw) {
  if (typeof raw !== "string" || !KEY.test(raw)) throw notFound();
  return raw;
}

export async function renameSessionType(ctx, rawKey, body) {
  if (!writableOwner(ctx)) throw notFound();
  const key = keyOf(rawKey);
  only(body, ["requestKey", "label", "expectedLabel"]);
  const requestKey = requestKeyOf(body);
  const label = labelOf(body);
  const expectedLabel = labelOf(body, "expectedLabel");
  const hash = hashOf({ op: "rename", key, label, expectedLabel });
  return write(ctx, {
    requestKey, hash,
    run: async (client, { owner, basis }) => {
      const row = await lockedType(client, owner, key);
      if (row.label !== expectedLabel) throw conflict("label_changed", "The name was changed meanwhile.", { current: view(row) });
      if (!row.is_active) throw conflict("type_archived", "Restore the session type before renaming it.", { current: view(row) });
      if (row.label === label) throw conflict("label_unchanged", "That is already its name.", { current: view(row) });
      const next = (await client.query(
        `update training.activity_types set label = $2 where key = $1 returning key, label, owner_scope, is_active, sort_order`, [key, label],
      )).rows[0];
      await log(client, ctx, { key, action: "rename", oldLabel: row.label, newLabel: label, basis, requestKey, hash });
      return { type: view(next) };
    },
  });
}

async function setActive(ctx, rawKey, body, active) {
  if (!writableOwner(ctx)) throw notFound();
  const key = keyOf(rawKey);
  only(body, ["requestKey"]);
  const requestKey = requestKeyOf(body);
  const op = active ? "restore" : "archive";
  const hash = hashOf({ op, key });
  return write(ctx, {
    requestKey, hash,
    run: async (client, { owner, basis }) => {
      const row = await lockedType(client, owner, key);
      if (row.is_active === active) throw conflict(active ? "type_active" : "type_archived", active ? "The session type is not archived." : "The session type is already archived.", { current: view(row) });
      const next = (await client.query(
        `update training.activity_types
            set is_active = $2, archived_at = case when $2 then null else now() end, archived_by_user_id = case when $2 then null else $3::uuid end
          where key = $1 returning key, label, owner_scope, is_active, sort_order`, [key, active, ctx.userId],
      )).rows[0];
      await log(client, ctx, { key, action: op, oldLabel: row.label, newLabel: row.label, basis, requestKey, hash });
      return { type: view(next) };
    },
  });
}

export const archiveSessionType = (ctx, key, body) => setActive(ctx, key, body, false);
export const restoreSessionType = (ctx, key, body) => setActive(ctx, key, body, true);
